101	  function renderPreflightResults(checks) {
102	    if (!checks || !checks.length) {
103	      resultsEl.innerHTML = '';
104	      allChecksPassed = false;
105	      startBtn.disabled = true;
106	      return;
107	    }
108	    allChecksPassed = checks.every(function (c) { return c.pass; });
109	    startBtn.disabled = !allChecksPassed;
110	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
111	
112	    var html = '<ul class="preflight-list">';
113	    checks.forEach(function (c) {
114	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
115	      html += '<li class="preflight-check ' + cls + '">';
116	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
117	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
118	      if (!c.pass && c.fix) {
119	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
120	      }
121	      html += '</li>';
122	    });
123	    html += '</ul>';
124	    resultsEl.innerHTML = html;
125	  }
126	
127	  // 5. Preflight button handler.
128	  preflightBtn.addEventListener('click', function () {
129	    var planPath = planInput.value.trim();
130	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
131	
132	    preflightBtn.disabled = true;
133	    preflightBtn.textContent = 'Running…';
134	    resultsEl.innerHTML = '<p class="text-muted">Running preflight checks…</p>';
135	    allChecksPassed = false;
136	    startBtn.disabled = true;
137	
138	    API.orchestratorStart(planPath, true).then(function (result) {
139	      renderPreflightResults((result && result.checks) ? result.checks : []);
140	    }).catch(function (err) {
141	      resultsEl.innerHTML = '<p class="error-banner">Preflight error: ' +
142	        escapeHtml((err && err.message) ? err.message : String(err)) + '</p>';
143	    }).then(function () {
144	      preflightBtn.disabled = false;
145	      preflightBtn.textContent = 'Run Preflight';
146	    });
147	  });
148	
149	  // 6. Start Run button handler.
150	  startBtn.addEventListener('click', function () {
151	    var planPath = planInput.value.trim();
152	    if (!planPath || !allChecksPassed) return;
153	
154	    startBtn.disabled = true;
155	    startBtn.textContent = 'Starting…';
156	
157	    API.orchestratorStart(planPath, false).then(function (result) {
158	      if (result && result.started) {
159	        var runStatusFilename = result.runStatusFilename || null;
160	        planInput.value = '';
161	        resultsEl.innerHTML =
162	          '<p class="success-banner">✓ Orchestrator launched' +
163	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
164	          '. Waiting for the run to appear in the queue below…</p>';
165	        allChecksPassed = false;
166	        startBtn.disabled = true;
167	        refreshQueue();
168	
169	        // Poll the run-status tombstone so we can surface fatal early
170	        // failures (e.g. invalid API key) that complete before the first
171	        // queue poll cycle.
172	        if (runStatusFilename) {
173	          var pollCount = 0;
174	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
175	          var statusPollTimer = setInterval(function () {
176	            pollCount++;
177	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
178	              if (!status) return; // file not yet written — run still in progress
179	              clearInterval(statusPollTimer);
180	              if (status.result === 'ERROR' && status.error) {
181	                resultsEl.innerHTML =
182	                  '<p class="error-banner">Run failed: ' +
183	                  escapeHtml(status.error) + '</p>';
184	              }
185	              // SUCCESS: queue will reflect the project; leave the banner.
186	            }).catch(function () {
187	              // Transient error — keep polling.
188	            });
189	            if (pollCount >= MAX_STATUS_POLLS) {
190	              clearInterval(statusPollTimer);
191	            }
192	          }, 2000);
193	          _orchStatusPollCleanups.push(function () { clearInterval(statusPollTimer); });
194	        }
195	      } else {
196	        // Checks re-evaluated by server — update the checklist.
197	        renderPreflightResults((result && result.checks) ? result.checks : []);
198	      }
199	    }).catch(function (err) {
200	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));

201	      startBtn.disabled = !allChecksPassed;
202	      startBtn.textContent = 'Start Run';
203	    }).then(function () {
204	      startBtn.textContent = 'Start Run';
205	    });
206	  });
207	
208	  // 7. Queue refresh and rendering — tracks expanded row IDs across refreshes.
209	  var expandedIds = {};
210	
211	  function refreshQueue() {
212	    // Stop log preview intervals started in the previous queue render.
213	    _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
214	    _orchLogPreviewCleanups = [];
215	
216	    var container = document.getElementById('orch-queue-container');
217	    if (!container) return;
218	
219	    API.orchestratorGetQueue().then(function (entries) {
220	      renderQueueTable(container, Array.isArray(entries) ? entries : []);
221	    }).catch(function () {
222	      // Best-effort polling — keep existing content on transient errors.
223	    });
224	  }
225	
226	  // ---- renderQueueTable helpers (closure-scoped) ----------------------------
227	
228	  /** Removes the success banner from the preflight results area, if present.
229	   *  Error banners are intentionally left intact.
230	   *
231	   *  Closure dependency: `resultsEl` — the #orch-preflight-results element
232	   *  captured by renderOrchestrator() at line 64. */
233	  function _clearSuccessBanner() {
234	    var successBanner = resultsEl.querySelector('.success-banner');
235	    if (successBanner) {
236	      successBanner.remove();
237	    }
238	  }
239	
240	  /** Builds the queue table HTML string from the entries array.
241	   *  Returns the complete <table>…</table> markup ready to be assigned to
242	   *  container.innerHTML. */
243	  function _buildQueueHtml(entries) {
244	    var html = '<table class="table orch-queue-table"><thead>' +
245	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
246	      '</thead><tbody>';
247	    entries.forEach(function (entry) {
248	      var id         = entry.id || '';
249	      var status     = entry.effectiveStatus || 'pending';
250	      var planName   = _orchBasename(entry.planPath || '');
251	      var elapsed    = _orchElapsed(entry.startedAt);
252	      var isExpanded = !!expandedIds[id];
253	      var statusBadgeHtml = '<span class="badge badge-' + escapeHtml(status) + '">' +
254	        escapeHtml(_orchStatusLabel(status)) + '</span>';
255	      // Progress cell: badge + text summary + optional log link.
256	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
257	      if (entry.progress) {
258	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
259	      }
260	      if (entry.logFilename && entry.expectedSlug) {
261	        progressHtml += ' <a href="#/projects/' +
262	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
263	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
264	      } else if (!entry.progress) {
265	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
266	      }
267	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
268	        ' data-entry-id="' + escapeHtml(id) + '">';
269	      html += '<td class="orch-toggle-cell">' +
270	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
271	        (isExpanded ? '▼' : '▶') + '</button></td>';
272	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
273	        escapeHtml(planName) + '</td>';
274	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
275	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
276	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
277	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
278	      html += '</tr>';
279	      if (isExpanded) {
280	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
281	          '<td colspan="6">' +
282	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
283	          '</td></tr>';
284	      }
285	    });
286	    html += '</tbody></table>';
287	    return html;
288	  }
289	
290	  /** Injects DOM-based action buttons and toggle listeners into the rendered
291	   *  table. Must be called after container.innerHTML has been set.
292	   *
293	   *  Branch priority (dismissibility-first):
294	   *    1. pending  → Kill button   (process is still running)
295	   *    2. dead     → Dismiss button (process has exited without completing)
296	   *    3. projectExists → View Project link (project ledger is on disk)
297	   *  The dead branch precedes the projectExists branch so that a dead entry
298	   *  that also has a known project slug always renders Dismiss, not View Project.
299	   *
300	   *  Closure dependencies (from renderOrchestrator() scope):
301	   *    `expandedIds`            — tracks which queue rows are expanded; mutated
302	   *                               by toggle clicks to persist state across refreshes.
303	   *    `refreshQueue`           — triggers a fresh API fetch + re-render after
304	   *                               a Kill/Dismiss action or toggle click. */
305	  function _bindQueueActions(container, entries) {
306	    entries.forEach(function (entry) {
307	      var id     = entry.id || '';
308	      var status = entry.effectiveStatus || 'pending';
309	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
310	      if (!cell) return;
311	
312	      if (status === 'pending') {
313	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
314	          delete expandedIds[id];
315	          refreshQueue();
316	        }));
317	      } else if (status === 'dead') {
318	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
319	          delete expandedIds[id];
320	          refreshQueue();

321	        }));
322	      } else if (entry.projectExists === true && entry.expectedSlug) {
323	        var link = document.createElement('a');
324	        link.href = '#/projects/' + encodeURIComponent(entry.expectedSlug);
325	        link.className = 'btn btn-sm btn-secondary orch-project-link';
326	        link.textContent = 'View Project';
327	        cell.appendChild(link);
328	      }
329	    });
330	
331	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
332	    Array.prototype.forEach.call(toggleBtns, function (btn) {
333	      btn.addEventListener('click', function () {
334	        var id = btn.getAttribute('data-entry-id');
